def b(op,value=0,target=1,**kw):return dict(op=op,value=value,target=target,**kw)
def scene(program,trigger='start',items=None):
 return dict(trigger=trigger,program=program,code='',players=[dict(x=110,y=345,avatar=None),dict(x=650,y=345,avatar=None)],items=items if items is not None else [dict(x=x,y=345) for x in (230,350,470)],hazards=[])
def code(blocks):
 lines=[]
 for x in blocks:
  op=x['op'];v=x['value']
  if op in ('right','left','up','down'):lines.append(f'move {op} {v}')
  elif op=='repeat':lines.append(f"repeat {x['count']} {x['direction']} {v}")
  elif op in ('say','ifwin'):lines.append(f'{op} "{v}"')
  elif op=='wait':lines.append(f'wait {v}')
  else:lines.append(op)
 return '\n'.join(lines)
