def enrich(l):
 path,day=l['path'],l['day'];l['success']=l['recall'];l['walkthrough']=[]
 if l['mode']=='browser':
  programs={'story':STORY,'game':GAME,'dev':DEV};l['starter']=programs[path][day];l['starterCode']=code(l['starter']);l['success']={'story':EXPECTED_STORY,'game':EXPECTED_GAME,'dev':EXPECTED_DEV}[path][day]
  s1=scene(l['starter']);s2=scene([b('say','The end!')],items=[])
  target=3;speed=3
  if (path=='story' and day in (12,24)):s1['trigger']='tap'
  if path=='story' and day==17:s2['trigger']='message';s2['program']=[b('say','Hello back!',2)]
  if path=='game' and day>=10:s1['trigger']='controls'
  if path=='game' and day in (5,6):s1['items']=[dict(x=230,y=345)];target=1
  if path=='game' and day in (11,13,14):s1['hazards']=[dict(x=290,y=345)]
  if path=='dev' and day==4:s1['items']=[dict(x=230,y=345)];target=1
  if path=='dev' and day==2:l['starterCode']='speed 3\nmove right 4'
  for s in (s1,s2):s['code']=code(s['program'])
  if path=='dev':s1['code']=l['starterCode']
  l['practice']=dict(schema=1,title=f"Practice: {l['title']}"[:80],theme='royal',mode='code' if path=='dev' else 'blocks',target=target,speed=speed,sound=True,scene=0,scenes=[s1,s2])
  l['walkthrough']=[NOTES.get((path,day),'Start from Scene 1. Keep Picture blocks for this activity.' if path!='dev' else 'Use Type commands. These teaching commands are not GDScript.'),'Follow the three quest steps above. Try the example only if you need a hint; change one thing and compare.','The example button changes commands only. Load practice stage also restores the example layout and triggers; download your creation before replacing it.']
  if path=='dev' and day in REFS:l['reference']=REFS[day]
 return l
